interactions.query:
query Doctor($owner0: String!, $name0: String!, $area: String!) {
  viewer { login }
  repo0: repository(owner: $owner0, name: $name0) { nameWithOwner hasIssuesEnabled
    labels(first: 100) { totalCount nodes { name } }
    area: labels(first: 100, query: $area) { nodes { name } }
  }
}
